import{_ as r,a as o,b as a}from"./chunks/9815578e5b5e2224c832.89gtURc9.js";import{_ as l,C as i,o as n,c as s,j as e,a as c,E as m,a6 as d}from"./chunks/framework.CnPv4DE1.js";const A=JSON.parse('{"title":"治愈平庸生活的良药（全方位变强）","description":"","frontmatter":{"title":"治愈平庸生活的良药（全方位变强）","originalTitle":"The Cure To A Mediocre Life (Become Multidimensionally Jacked)","date":"2023-08-18","originalUrl":"https://thedankoe.com/letters/the-cure-to-a-mediocre-life-become-multidimensionally-jacked/","minutes":11,"sourceHash":"cbf9088a5a29f80b33fc9dfce4c81ed66830a969db535aaa49ed7755ca126d95","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-cure-to-a-mediocre-life-become-multidimensionally-jacked/"}]]},"headers":[],"relativePath":"letters/the-cure-to-a-mediocre-life-become-multidimensionally-jacked.md","filePath":"letters/the-cure-to-a-mediocre-life-become-multidimensionally-jacked.md"}'),h={name:"letters/the-cure-to-a-mediocre-life-become-multidimensionally-jacked.md"};function g(u,p,f,_,b,k){const t=i("ArticleMeta");return n(),s("div",null,[p[0]||(p[0]=e("h1",{id:"治愈平庸生活的良药-全方位变强",tabindex:"-1"},[c("治愈平庸生活的良药（全方位变强） "),e("a",{class:"header-anchor",href:"#治愈平庸生活的良药-全方位变强","aria-label":'Permalink to "治愈平庸生活的良药（全方位变强）"'},"​")],-1)),m(t),p[1]||(p[1]=d('<p><a href="https://www.youtube.com/embed/eDoUahe4BLk?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>不知为何，我一直有一种冲动，想要把生活的每一个领域都“拉满”。</p><p>我把生活看作是一场电子游戏。</p><p>我的头脑、身体、精神和财务状况，都是我必须积累经验值的能力属性。</p><p>我想要全方位变强。</p><p>也许是因为我很早就开始质疑那条默认的人生路径。</p><p>也许是因为我注意到人们看起来有多么不快乐、超重和痛苦。</p><p>也许是因为我观察到，人们是如何通过走上一条特定的人生道路来限制自己的机会的。</p><p>随波逐流毫无意义，因为那只会造就大多数人拥有的人生，而那并不美好。</p><p>默认人生路径的问题在于专业化、割裂化和过度局限于细分领域。</p><p>我们被训练去关注一个孤立的点，而不是连接这些点的线。</p><p>在学校里，我们学习生物、化学、数学、文学等等。我们去上各自独立的课程，却不把它们之间的点连接起来。这缺乏整体性、创造力，以及那种能带来超常结果的实用性。</p><p>毕业后，我们进一步将思维局限在我们<em>自以为</em>余生想成为的角色上。</p><p>作为青少年，我们被期望在甚至还没有开始真实生活的时候，就从无数的人生道路中选择<em>一条</em>。我们怎么可能确切知道自己想要什么？似乎没有比余生只专注于一件事更糟糕的痛苦配方了。</p><p>这剥夺了我们的好奇心和创造力。</p><p>它导致了这样一个世界：战士没脑子，知识分子没种。</p><p>一个“哲学家”会忽略生活中实际的一面，因为他们是知识分子。但哲学的主要问题是“一个人如何过上好日子？”如果一个哲学家不能建立一家企业、放松自己的头脑、或者成为一个社交达人，那么他们的哲学就毫无意义。</p><p>科学家会把青蛙扔进搅拌机来检查它的各个部位。他们会有一些发现，但远不及他们进行整体研究时的发现多。</p><p>与其只看青蛙的身体碎片，你可以研究它的生存环境、交配模式、决策过程和饮食习惯，而不是顾此失彼。</p><p>割裂式学习的后果摧毁了我们个人的潜力。</p><h2 id="现代文艺复兴人" tabindex="-1">现代文艺复兴人 <a class="header-anchor" href="#现代文艺复兴人" aria-label="Permalink to &quot;现代文艺复兴人&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>一出生，我们就被人规定了一种生活方式。</p><p>去上学，找份工作，找个伴侣，努力挤出时间做点让生活美好的活动，65岁退休，然后永远不再工作——然而工作本应是生活中不可或缺的一部分，理应包含将我们的注意力投入到我们认为愉快的事情上。</p><p>在学校里，我们被告知要选一个专业。</p><p>在商业中，我们被告知要选一个细分领域。</p><p>于是我们忽略了其他领域的学习，结果大打折扣。</p><p>创造力是通往财富（精神和财务上）的道路，而创造力需要对解决特定问题有高度的理解。</p><p>我们正处于第二个黄金时代的中心。</p><p>互联网上的信息如此之多，以至于令人应接不暇。你不可能学完所有东西，但你能学到很多。</p><p>人们仍然生活在必须精通<em>一</em>件事的范式中，因为在过去，这就是环境对成功的需求。</p><p>现在，成功是为<a href="/letters/the-value-creator-a-new-internet-career-path-for-intelligent-people">价值创作者 (value creator)</a>保留的。他们是专业化的通才。是新时代的文艺复兴人。是数字时代的文艺复兴人。是那种能够钻研各种兴趣、从中创造价值，并维持一种愉快生活方式的人，正如我在<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学 (Digital Economics)</a>中所教的那样。</p><p>我们生活在一个有趣的时代。</p><p>这里有着海量的信息，但它只对那些学习没有目标或意图的人来说才会显得压抑。</p><p>创作者经济应运而生，各种课程开始将信息浓缩为可执行的商业模式和人生建议。</p><p>内容、课程和书籍就像是现代世界的精神压缩包。</p><p>你不再需要花上4到12年的时间、4万美元以及一纸文凭来赚取一份可替代的收入。</p><p>但是，这意味着你需要承担个人责任。</p><p>没有人会手把手教你。</p><p>以下是你应该做的：</p><p><strong>1) 我是无名之辈</strong></p><p>抛弃所有标签。</p><p>成为万物。</p><p>做个设计师、作家、营销人员、社交达人、跑步者、健美者、哲学家、科学家、心理学家，做一个懂得如何维持自己那份痴迷般好奇心的博学者。</p><p>认同单一的技能、意识形态或身份，会在任何情况下限制你的潜力。</p><p>宇宙是一个变形者。它处于不断的流动之中。海洋蒸发，在云层中凝结，化作雨水降落成水洼，然后水无可避免地又会找回它的归途。</p><p>没有什么是永恒不变的。</p><p>你的细胞和几年前完全不同了。你的兴趣允许被改变。你的思想允许被改变。你也允许改变。</p><p>成为宇宙。</p><p><strong>2) 好奇心指南针</strong></p><p>小时候，大人们总会打击你“只是三分钟热度”。</p><p>我有过我的非主流（emo）时期、健身房兄弟（gym bro）时期，甚至我的狂欢派对（raver）时期。所有这些都塑造了今天的我。</p><p>尝试绝对没有错。但盲从他人的意愿绝对是有问题的。</p><p>处方、路线图和漫长的课程体系本身并不坏，但它们会把你的思维局限在一个特定的结果上，并用特定的建议来实现这个目标。</p><p>这很有用，但不应该被视为一劳永逸的事情。那样你就会陷入悲惨的生活。</p><p>在我自己以及我渴望成为的人身上，我注意到了一个共同的模式：</p><p>他们不会把学习限制在某一件事上。</p><p>万物互联。</p><p>通过追求你好奇的事物，你不仅有了学习的动力，而且模式识别还能增加有益的多巴胺，并巩固高层次的知识。</p><p>“专注一件事”是个好建议，但前提是这件事得是一个庞大的、实质性的、有意义的目标，它需要你调动大量的兴趣、技能和经验才能实现。</p><p>我在商业上的“闪亮物体综合症”造就了我今天的网络形象。我的品牌、内容和产品，都是我技能和兴趣独特结合的顶点。</p><p>花1到2个月的时间，对一个主题、技能或兴趣产生痴迷般的好奇心，并把它加入你的思想工具箱，这是明智之举。随着你体验生活，这只会提高你对机遇的敏锐度。</p><p>当你局限于细分领域（时间太长，或钻得太深）时，你就会变成一个缺乏深度和个性的、被美化了的搜索引擎。</p><p>如果你想公开分享你的好奇心（以一种能带来职业机会和成就感的方式），去看看<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">两小时作家 (2 Hour Writer)</a>。</p><p><strong>3) 投资你的教育</strong></p><p>这一生，你只拥有一件东西：你的头脑。</p><p>其他一切都可以被剥夺。</p><p>学校系统有一点做得很对，那就是为了美好的未来而进行的持续、每日的教育。</p><p>但是，学校并不优先考虑好奇心，所以大多数人在毕业时都非常讨厌学习。</p><p>学习是人类体验的基础。</p><p>把它死死钉进你的脑子里：你必须每天学习，学什么都行。不管是10分钟还是3小时，你的未来全靠它了。</p><p>如果你不先去了解新机会，你还能怎么发现它们？你又怎么能对那些在你看来根本不存在的机会采取行动？</p><p>当你停止学习，你的生活就停止了进步。你停止了成长。心理上的益处和让人愉悦的化学物质也停止了流动。生活变得平庸而重复。你变得机械，像个机器人。</p><p>我们已经谈了很多关于学习的内容，但如果没有去构建，学习就毫无意义。</p><h2 id="成为一个建设者" tabindex="-1">成为一个建设者 <a class="header-anchor" href="#成为一个建设者" aria-label="Permalink to &quot;成为一个建设者&quot;">​</a></h2><p>在我的新书<a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">《专注的艺术》(The Art Of Focus，即将出版)</a> 中，我有一节专门探讨建设者的哲学。</p><p>在我的生活中，我注意到的一个模式是，我总是会挤出时间来建设属于我自己的东西。</p><p>学校作业、客户工作以及工作中分配给我的项目都是必要的，但并没有带给我我想要的成就感。</p><p>我的生活就是一个元项目，它是通过一系列个人和商业项目构建而成的。</p><p>项目为你学习的注意力设定了框架。</p><p>当你的注意力集中在你正在建设的事物上时，你接触到的所有信息都会通过这个镜头被过滤。</p><p>学习的源泉是挣扎，而不是死记硬背。你必须遇到问题，找到解决问题的方法，并将其融入你的生活。</p><p>要识别问题，你需要一个目标。</p><p>要解决问题，你需要创造一个解决方案。</p><p>要创造解决方案，你需要一个项目，让你在接下来的1到6个月里投入你的注意力。</p><p>当我说项目时，我指的是可衡量且有记录的东西。它不一定非得是个实体产品。</p><p>它可以很简单，比如拥有一本力量训练日志、记录你的饮食、追踪你的体重，并研究健身信息来加速你的进度。</p><p>让我们从这里开始。</p><p><strong>1) 巨大的非理性目标，微小的理性步骤</strong></p><p><img src="'+o+'" alt=""></p><p>大目标比小目标好，因为它们为你提供了坚持到底所必需的愿景、动力和长期专注力。</p><p>相比起每天发送10条社交私信，在1年内建立一个百万美元的企业让我兴奋得多。</p><p>相比起为这一周准备备餐，今年夏天在海滩上秀出肌肉分明的身材让我兴奋得多。</p><p>为了踏上全方位变强的旅程，请为你生活的主要支柱设定一个大目标。</p><ul><li><strong>头脑</strong> – 你想如何处理情绪和压力？你想拥有和别人一样平庸的心态吗？</li><li><strong>身体</strong> – 你想看起来怎样、感觉怎样？这将如何影响你生活的其他领域（比如别人如何看待你并向你提供机会）？</li><li><strong>精神</strong> – 你是否觉得生活缺乏意义、惊喜和成就感？你觉得是生活在摆布你，还是你在与生活顺流而行？</li><li><strong>商业</strong> – 你想赚多少钱？为什么？你想让这些钱来自一项有意义的努力，而不是像90%的工作那样吗？</li></ul><p>我强烈建议你花10到20分钟在日记里写写这些。它们对你的生活有什么影响？</p><p>问题是，人们在这里就停滞不前了。</p><p>他们对着自己的目标精神意淫，却从未朝着目标取得任何有意义的进展。</p><p><strong>2) 为生活中的每个领域勾勒一个项目</strong></p><p>目标是“做什么”，愿景是“为什么”，而项目是“怎么做”。</p><p>既然我们对大目标有了愿景和动力，我们还需要获得清晰度。</p><p>项目有目标、流程，以及需要每天优先攻克的行动。</p><p>你每天能做些什么来推动自己朝着目标前进？</p><p>为了做出更好的决定，你需要对目标的哪些方面进行自我教育？</p><p>你如何记录你的进度，从而保持动力，让你明天还想继续？</p><p>在你写下目标的那个笔记本里，为每个目标创建一个简单的项目：</p><ul><li><strong>里程碑</strong> – 写下附带合理时间表的切实里程碑。</li><li><strong>变量</strong> – 写出能帮助你达成目标的每个变量（对于健康：营养、训练、睡眠。对于商业：产品、引流、内容）。</li><li><strong>原则</strong> – 那些能带来实质性进展的优先行动。</li><li><strong>技能</strong> – 为实现该目标你必须习得的技能。</li></ul><p>这让改变生活这件事变得更加清晰。</p><p><strong>3) 先开始，再学习</strong></p><p>如果你想学得更快，别从学习开始。</p><ol><li>规划一个项目</li><li>开始构建它</li><li>在过程中学习</li></ol><p>太多人陷入了“教程地狱”，把无用的知识堆砌成大脑迷雾。</p><p>开始行动，遇到问题，然后尝试用不同的技巧去解决那个问题。</p><p>当年我学 Photoshop 的时候，我试图在开始之前学会这款软件的所有功能。</p><p>而当我真正开始操作时，我觉得自己简直一无所知。</p><p>我不得不额外去搜具体的教程和“跟我一起做”的视频，直到弄明白如何做出我想要的效果。</p><p>我意识到的是，解决问题的方法不止一种。</p><p>如果我想抠掉像树一样复杂的背景，我可以用钢笔工具、颜色通道、色彩范围，或者快速选择工具。</p><p>快速选择工具是每个人都会用的，而它通常会导致最差的效果。</p><p>在你研究任何事物时，都要牢记这一点。</p><p>如果任何人都能用容易获取的信息来解决问题，那么很可能有一种更好的方法能让你在竞争中获得优势。</p><p>现在，我不想让这听起来像是在说，除非遇到问题，否则你<em>绝不</em>应该去学习。</p><p>恰恰相反。</p><p>我强烈建议你养成广泛学习的习惯。</p><p>每天花10到30分钟，让自己沉浸在与你目标相关的信息中。</p><p>看一部你感兴趣的 YouTube 视频。买一本畅销书。为下一次散步排好播客的播放列表（并且开始去散步……我保证，如果你不出门，你是坚持不了这种学习习惯的。家里的干扰太多了）。</p><p><strong>4) 通过习惯养成设计生活方式</strong></p><p><img src="'+a+'" alt=""></p><p>现在的你和你想成为的人之间的差距，在于构成你生活方式的习惯。</p><p>想一想吧。</p><p>那些在精神、身体或财务上极其强悍的人，难道某天一觉醒来就拥有了最顶级的头脑、身材和事业吗？</p><p>还是说，他们每天都会采取微小的行动，以此维持进度并向着更美好的未来添砖加瓦？</p><p>大多数人会告诉你别再打游戏、别出去浪、别让自己分心……我同意，但我也不全同意。</p><p>我偶尔还是会打打游戏。大概一周5个小时。</p><p>我依然会和朋友出去玩到深夜。大概一个月2到5次。</p><p>我之所以还能把99%的人甩在身后，是因为我把那些能带来实质性进展的任务前置到了早晨。</p><p>在早上5点到11点之间，我：</p><ul><li>每周跑步3到4天</li><li>花1小时写我的新闻通讯和内容（这维持着我95%的业务……记住，这就是原则）。</li><li>推进一个新项目，目前是我的新书发布和软件公司</li><li>每周去健身房6到7天</li><li>在所有这些活动之间去散步</li><li>烹饪只需10到15分钟就能准备好的高营养餐（我也经常在外面吃晚饭——我现在每天摄入约4500卡路里）</li></ul><p>我知道由于时间限制，不是每个人都能做到这些，但我过去也一样做不到。</p><p>随着你的努力取得成果，你做事的效率也会越来越高。时间会被解放出来（因为这应该是你设定的几乎每个目标的子目标……这是衡量进度的一个极佳方式）。</p><p>如果你拿不定主意：</p><p>早起一小时，就能解锁那段免受干扰的时间，它将解决你大部分的问题。</p><p>朋友们，这期的内容就到这里。</p><p>致多维强悍的你，</p><p>– Dan Koe</p><hr><p><a href="/en/letters/the-cure-to-a-mediocre-life-become-multidimensionally-jacked">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',147))])}const x=l(h,[["render",g]]);export{A as __pageData,x as default};
